package com.appnexus.platform.persistence.platformscope;
import com.appnexus.platform.persistence.PlatformScoped;
import java.util.*;
import org.apache.ibatis.annotations.*;
/** 数据范围解析 Mapper；只返回已通过有效主体、角色和权限连接验证的结构化策略。 */
@Mapper
@PlatformScoped(tables={"identity_account","platform_tenant","tenant_member","organization_capability_grant","access_member_role","access_member_permission","access_role","access_role_permission","access_permission","access_role_data_policy","access_role_data_policy_organization"})
public interface DataScopeMapper {
 @Select("SELECT dp.scope_type,BIN_TO_UUID(o.organization_id) organization_id FROM tenant_member m JOIN identity_account a ON a.id=m.account_id JOIN platform_tenant t ON t.id=m.tenant_id JOIN access_member_role mr ON mr.tenant_id=m.tenant_id AND mr.member_id=m.id JOIN access_role r ON r.id=mr.role_id AND r.tenant_id=m.tenant_id JOIN access_role_permission rp ON rp.role_id=r.id JOIN access_permission p ON p.id=rp.permission_id JOIN access_role_data_policy dp ON dp.role_id=r.id AND dp.permission_id=p.id LEFT JOIN access_role_data_policy_organization o ON o.role_id=dp.role_id AND o.permission_id=dp.permission_id AND o.tenant_id=m.tenant_id WHERE m.tenant_id=UUID_TO_BIN(#{tenant}) AND m.id=UUID_TO_BIN(#{member}) AND m.account_id=UUID_TO_BIN(#{account}) AND m.enabled=TRUE AND a.enabled=TRUE AND t.enabled=TRUE AND r.status='ENABLED' AND r.deleted_at IS NULL AND p.enabled=TRUE AND p.code=#{code} AND dp.resource_type=#{resource} ORDER BY dp.scope_type,o.organization_id")
 List<Map<String,Object>> policies(@Param("account") String account,@Param("tenant") String tenant,@Param("member") String member,@Param("code") String code,@Param("resource") String resource);
 @Select("SELECT (EXISTS(SELECT 1 FROM access_member_permission mp JOIN tenant_member m ON m.tenant_id=mp.tenant_id AND m.id=mp.member_id JOIN identity_account a ON a.id=m.account_id JOIN platform_tenant t ON t.id=m.tenant_id WHERE mp.tenant_id=UUID_TO_BIN(#{tenant}) AND mp.member_id=UUID_TO_BIN(#{member}) AND m.account_id=UUID_TO_BIN(#{account}) AND mp.permission_code=#{code} AND m.enabled=TRUE AND a.enabled=TRUE AND t.enabled=TRUE AND (mp.expires_at IS NULL OR mp.expires_at>CURRENT_TIMESTAMP(6))) OR EXISTS(SELECT 1 FROM organization_capability_grant g JOIN tenant_member m ON m.tenant_id=g.tenant_id AND m.id=g.member_id JOIN identity_account a ON a.id=m.account_id JOIN platform_tenant t ON t.id=m.tenant_id WHERE g.tenant_id=UUID_TO_BIN(#{tenant}) AND g.member_id=UUID_TO_BIN(#{member}) AND m.account_id=UUID_TO_BIN(#{account}) AND g.capability=UPPER(SUBSTRING_INDEX(#{code},':',-1)) AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>CURRENT_TIMESTAMP(6)) AND m.enabled=TRUE AND a.enabled=TRUE AND t.enabled=TRUE))")
 boolean legacyAll(@Param("account") String account,@Param("tenant") String tenant,@Param("member") String member,@Param("code") String code);
}
